mapper.select:
SELECT 
FROM bt_table_model_item a
WHERE a.status_cd = '00A'
  AND a.item_id = #{itemId}
  AND a.tenant_id = #{tenantId}

SELECT 
FROM bt_table_model_item a
WHERE a.status_cd = '00A'
  AND a.tenant_id = #{tenantId}

  AND a.table_id = #{tableId}

ORDER BY a.updated_time DESC

SELECT a.item_id, a.table_id, a.change_sql, a.tenant_id, s.data_source_code FROM bt_table_model_item a JOIN bt_data_table b ON b.table_id = a.table_id AND b.tenant_id = a.tenant_id JOIN bt_data_source s ON s.data_source_id = b.data_source_id AND s.tenant_id = b.tenant_id WHERE a.status_cd = '00A' AND a.tenant_id = #{tenantId}
AND a.table_id IN (#{tableId})
ORDER BY a.item_id
